import React from 'react';

const TABS = [
  { id:'home',      label:'Hem' },
  { id:'checkin',   label:'Check-in' },
  { id:'history',   label:'Historik' },
  { id:'breathing', label:'Andning' },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position:'fixed', bottom:20, left:'50%', transform:'translateX(-50%)',
      zIndex:100, display:'flex', alignItems:'center',
      background:'rgba(17,16,16,0.88)',
      backdropFilter:'blur(20px)',
      border:'1px solid rgba(255,255,255,0.06)',
      borderRadius:100, padding:'5px 5px',
      boxShadow:'0 8px 40px rgba(0,0,0,0.15)',
    }}>
      {TABS.map(tab => (
        <button key={tab.id} onClick={() => setPage(tab.id)}
          style={{
            padding:'8px 16px', borderRadius:100, border:'none',
            background: page===tab.id ? 'rgba(240,237,232,0.12)' : 'transparent',
            transition:'all .2s',
          }}>
          <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.1em', textTransform:'uppercase', color: page===tab.id ? 'rgba(240,237,232,0.85)' : 'rgba(240,237,232,0.28)', transition:'color .2s' }}>
            {tab.label}
          </span>
        </button>
      ))}
    </div>
  );
}
